  let best = null;
  for (const k of Object.keys(ctx.files)) {
    const m = /^rulebook\/([^/]+)\/edition\.json$/.exec(k);
    if (!m) continue;
    const from = String(jsonOf(ctx.files[k])?.effectiveFrom ?? '');
    if (from && from <= day && (!best || from > best.from)) best = { dir: m[1], from };
